<header class="page-header"><div><h1><?= e(t('Weekly parent report')) ?></h1><p><?= e($report['start']) ?> – <?= e($report['end']) ?></p></div><a href="/school"><?= e(t('School tools')) ?></a></header>
<section class="card"><form class="inline" method="get" action="/school/report"><label><?= e(t('Week containing')) ?><input type="date" name="date" value="<?= e($report['start']) ?>" required></label><button><?= e(t('View week')) ?></button></form><p><?= e(t('Reading:')) ?> <?= e($report['reading_pages']) ?> <?= e(t('pages · Study:')) ?> <?= e($report['study_minutes']) ?> <?= e(t('recorded minutes.')) ?></p><h2><?= e(t('Completed work')) ?></h2><?php if(!$report['completed']): ?><p><?= e(t('No completed work recorded in this week.')) ?></p><?php endif; ?><ul><?php foreach($report['completed']as $title): ?><li><?= e($title) ?></li><?php endforeach; ?></ul><h2><?= e(t('Shared mood trend')) ?></h2><p class="muted"><?= e(t('Only check-ins explicitly shared with a guardian are included. Private notes are excluded.')) ?></p><?php foreach($report['shared_moods']as $row): ?><p><?= e($row['date']) ?> · <?= e(SchoolService::options('mood')[$row['mood']]) ?></p><?php endforeach; ?><p><?= e(t('Use Print / Save as PDF to export this report. Sharing the resulting file is your choice.')) ?></p></section>
